package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Objeto que expone una única instancia de Retrofit configurada para consumir la API de Ragnarok.
 * De esta forma todos los colaboradores (repositorios, pruebas) reutilizan la misma
 * configuración base sin duplicar código.
 */
object NetworkModule {

    // Para emulador Android: 10.0.2.2 apunta al localhost del host (tu PC)
    // Para dispositivo físico: usa la IP de tu PC en la red (ej. 192.168.1.42)
    private const val BASE_URL = "http://10.0.2.2:8000/api/v1/"

    /**
     * Retrofit se crea de forma lazy para no inicializar la red hasta que realmente
     * se necesite. GsonConverterFactory se encarga de mapear JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.data.remote

import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory

/**
 * Object that exposes a single Retrofit instance configured to consume the Ragnarok API.
 * This way all collaborators (repositories, tests) reuse the same
 * base configuration without duplicating code.
 */
object NetworkModule {

    // For Android emulator: 10.0.2.2 points to the host's localhost (your PC)
    // For physical device: use your PC's IP on the network (e.g. 192.168.1.42)
    private const val BASE_URL = "http://10.0.2.2:8000/api/v1/"

    /**
     * Retrofit is created lazily to not initialize the network until it's actually
     * needed. GsonConverterFactory handles mapping JSON ↔ data class.
     */
    val api: RagnarokApiService by lazy {
        Retrofit.Builder()
            .baseUrl(BASE_URL)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
            .create(RagnarokApiService::class.java)
    }
}

package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaración de los endpoints que usamos de la API de Ragnarok.
 * Retrofit genera la implementación concreta en base a esta interfaz.
 */
interface RagnarokApiService {

    /**
     * Recupera el detalle de un item por su ID.
     * La API acepta el identificador numérico en el endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Recupera el detalle de un monstruo por su ID.
     * La API acepta el identificador numérico en el endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Obtiene los ítems populares según el período de tiempo especificado.
     * period puede ser: today, yesterday, last7days, last30days
     * limit controla cuántos elementos trae la respuesta (por defecto 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse
}

package com.example.ragnarokdatabase.data.remote

import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.Monster
import com.example.ragnarokdatabase.model.PopularItemsResponse
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

/**
 * Declaration of the endpoints we use from the Ragnarok API.
 * Retrofit generates the concrete implementation based on this interface.
 */
interface RagnarokApiService {

    /**
     * Retrieves the details of an item by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("items/{id}")
    suspend fun getItem(@Path("id") itemId: Int): Item

    /**
     * Retrieves the details of a monster by its ID.
     * The API accepts the numeric identifier in the endpoint.
     */
    @GET("monsters/{id}")
    suspend fun getMonster(@Path("id") monsterId: Int): Monster

    /**
     * Gets popular items according to the specified time period.
     * period can be: today, yesterday, last7days, last30days
     * limit controls how many items the response brings (default 10)
     */
    @GET("items/popular/{period}")
    suspend fun getPopularItems(
        @Path("period") period: String,
        @Query("limit") limit: Int = 10
    ): PopularItemsResponse
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem

/**
 * Encapsula el acceso a la red para que el resto de capas desconozcan
 * si los datos provienen de la web, de un caché o de una base local.
 * Aquí es donde podríamos combinar múltiples fuentes sin cambiar la UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Consulta el detalle de un item por su ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Obtiene los ítems populares según el período de tiempo.
     * period puede ser: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }
}

package com.example.ragnarokdatabase.data.repository

import com.example.ragnarokdatabase.data.remote.NetworkModule
import com.example.ragnarokdatabase.data.remote.RagnarokApiService
import com.example.ragnarokdatabase.model.Item
import com.example.ragnarokdatabase.model.PopularItem

/**
 * Encapsulates network access so that the rest of the layers don't know
 * whether the data comes from the web, cache, or a local database.
 * This is where we could combine multiple sources without changing the UI.
 */
class ItemRepository(
    private val api: RagnarokApiService = NetworkModule.api
) {
    /**
     * Queries the details of an item by its ID.
     */
    suspend fun getItem(itemId: Int): Item {
        return api.getItem(itemId)
    }

    /**
     * Gets popular items according to the time period.
     * period can be: today, yesterday, last7days, last30days
     */
    suspend fun getPopularItems(period: String, limit: Int = 10): List<PopularItem> {
        return api.getPopularItems(period, limit).items
    }
}

